(()=>{'use strict';const $=id=>document.getElementById(id),M=CultureModels,id=document.body.dataset.lesson,type=id.split('-')[0],course=CATALOG.find(c=>c.id===id),steps=M.steps[type],layoutStep={soil:4,sand:6,hydro:4}[type],resultStep=steps.length-1,observeStep=resultStep-1;
const state={type,step:0,operation:0,treatment:1,day:28,volume:5,phase:0,fraction:0,cycle:false,cycleClock:0,aeration:true,waterAdded:false,renewed:false,layout:M.layout(73),seed:73};
document.body.classList.add('culture');document.title=course.title+' · 磷效应研究';$('title').textContent=course.title;$('stage-keyword').textContent='同一玉米 · 三个磷水平 · 独立重复';
const w=new PlantWorld.World($('scene'),{extent:type==='sand'?17.2:14,target:type==='sand'?1.7:2.1,yaw:-.24,pitch:.24});w.draw=world=>CultureWorlds.draw(world,state);w.sky=function(){PlantWorld.World.prototype.sky.call(this,false)};
const panel=document.createElement('aside');panel.className='culture-panel';panel.setAttribute('aria-label','试验步骤与机理');panel.innerHTML='<div class="c-eyebrow" id="c-eyebrow"></div><h2 id="c-heading"></h2><div class="c-chain" id="c-chain"></div><div id="c-operations" class="c-operations" role="group" aria-label="本步操作"></div><ol id="c-points"></ol><div id="c-live" class="c-live" aria-live="polite"></div><div id="c-results"></div><details id="c-recipe"><summary>配方与本处理用量</summary><div id="c-recipe-body"></div></details><details><summary>试验依据与边界</summary><p>依据本地《植物营养研究法电子书》第一章的土培、溶液培养与砂砾培养技术。处理浓度、28 天终点和观测值是教学设定，动画不是实测生长或输液动力学。</p><a href="https://github.com/Lidong-Huang/plant-nutrition-lab/blob/main/docs/磷效应培养试验.md" target="_blank" rel="noopener">完整步骤、配方与教材对应 ↗</a></details><div class="c-siblings"><a href="https://lidong-huang.github.io/plant-nutrition-lab/lessons/soil-culture.html">土培</a><a href="https://lidong-huang.github.io/plant-nutrition-lab/lessons/sand-culture.html">砂培</a><a href="https://lidong-huang.github.io/plant-nutrition-lab/lessons/hydro-culture.html">水培</a></div>';document.querySelector('.stage').append(panel);
const legend=document.createElement('div');legend.className='culture-legend';legend.innerHTML='<span>剖视 · 根区需遮光</span><span>青色：P 迁移示意</span>'+(type==='sand'?'<span>橙色气路 / 蓝色液流</span>':'');document.querySelector('.stage').append(legend);
steps.forEach((s,i)=>{const b=document.createElement('button');b.innerHTML=`<span>${String(i+1).padStart(2,'0')}</span>${s[0]}`;b.onclick=()=>{stop();setStep(i)};$('steps').append(b)});
let autoTimer=null,auto=false;
function stop(){clearInterval(autoTimer);autoTimer=null;auto=false;$('play').textContent='▶';$('play').setAttribute('aria-pressed','false')}
function setStep(i){state.step=Math.max(0,Math.min(steps.length-1,i));state.operation=0;state.cycle=false;state.fraction=.5;if(type==='sand')state.phase=state.step===4?1:state.step===5?2:0;state.waterAdded=false;state.renewed=false;w.autoRotate=false;$('rotate').setAttribute('aria-pressed','false');const grid=state.step===layoutStep,compare=state.step>=observeStep;w.extent=grid?15.8:compare?14.8:type==='sand'?17.2:14;w.target=grid?.6:type==='sand'&&!compare?1.7:2.1;if(CulturePractical.get(type,state.step)){w.target=type==='hydro'&&state.step===3?1.65:1.1;w.extent=14}update()}
function button(id,text,fn,active=false){const b=document.createElement('button');b.id=id;b.className='c-control';b.textContent=text;b.setAttribute('aria-pressed',String(active));b.onclick=()=>{stop();fn();update()};$('controls').append(b);return b}
function slider(id,label,min,max,value,fn,unit=''){const l=document.createElement('label');l.htmlFor=id;l.innerHTML=`<span>${label}</span><output>${value}${unit}</output><input id="${id}" type="range" min="${min}" max="${max}" step="1" value="${value}" aria-label="${label}">`;l.querySelector('input').oninput=e=>{stop();fn(Number(e.target.value));l.querySelector('output').textContent=e.target.value+unit;refreshPanel()};$('controls').append(l)}
function controls(){const a=$('controls');a.replaceChildren();if(state.step===layoutStep){button('c-shuffle','区组内重新随机 ↻',()=>{state.layout=M.layout(++state.seed)});return}
if(type==='sand'&&[3,4,5].includes(state.step)){button('c-cycle',state.cycle?'暂停循环':'播放完整循环',()=>{state.cycle=!state.cycle;state.cycleClock=state.phase*4+state.fraction*4;w.paused=false;motion()},state.cycle);button('c-phase','下一阶段 →',()=>{state.cycle=false;state.phase=(state.phase+1)%4;state.fraction=.5});return}
if(type==='soil'&&state.step===5){button('c-water',state.waterAdded?'已补水 250 g':'称重后补水',()=>state.waterAdded=!state.waterAdded,state.waterAdded);return}
if(type==='hydro'&&state.step===5){button('c-air',state.aeration?'通气：开':'通气：关',()=>state.aeration=!state.aeration,state.aeration);button('c-renew','换成本处理新液',()=>state.renewed=!state.renewed,state.renewed);return}
if(state.step===observeStep){slider('c-day','处理后',0,28,state.day,v=>state.day=v,' 天');return}
if(state.step===resultStep){button('c-csv','下载模拟观测 CSV ↓',download);return}
for(let t=0;t<3;t++)button('c-treatment-'+t,`${M.treatments[t]} ${type==='soil'?M.soilP[t]+' mg P/kg':M.solutionP[t].toFixed(2)+' mmol P/L'}`,()=>state.treatment=t,state.treatment===t);}
function recipe(){const d=M.dose(type,state.treatment,type==='soil'?5:state.volume),fmt=n=>n.toFixed(1);if(type==='soil')return `<p>5 kg 干土，元素 P ${d.pMg.toFixed(0)} mg / 盆。</p><table><tr><th>本处理</th><th>mg / 盆</th></tr><tr><td>KH₂PO₄</td><td>${fmt(d.kh2po4Mg)}</td></tr><tr><td>KCl 补钾</td><td>${fmt(d.kclMg)}</td></tr></table><p>三个处理总 K 同为 750 mg / 盆；此处 KCl 是全部补钾量，不能再额外施同量钾底肥。N 与其他背景养分另行统一。P 为 0 / 25 / 75 mg/kg，是教学梯度，不是施肥推荐。</p>`;
return `<p>改良半量霍格兰（一），本独立系统初始液量 ${state.volume} L。</p><table><tr><th>组分</th><th>mmol/L</th></tr><tr><td>KNO₃</td><td>2.50</td></tr><tr><td>Ca(NO₃)₂</td><td>2.50</td></tr><tr><td>MgSO₄</td><td>1.00</td></tr><tr><td>KH₂PO₄</td><td>${d.pMmol.toFixed(2)}</td></tr><tr><td>KCl</td><td>${d.kclMmol.toFixed(2)}</td></tr></table><p>本份 KH₂PO₄ ${fmt(d.kh2po4Mg)} mg；KCl ${fmt(d.kclMg)} mg；含元素 P ${fmt(d.pMg)} mg（${d.pMgL.toFixed(2)} mg P/L）。钙盐与镁盐的称量须匹配结晶水。</p><p>各处理相同的微量元素（µmol/L）：B 23、Mn 4.5、Zn 0.38、Cu 0.16、Mo 0.05、Ni 0.05；Fe-EDTA 按 Fe 25。Ni 为现代完整营养背景补充，非教材原表逐项照抄。</p><p>K=3.00，N=7.50，Ca=2.50，Mg=1.00，S=1.00 mmol/L。Cl⁻ 随补钾改变；配平主元素不等于所有阴离子完全相同。具体微量盐和配液顺序见完整文档。</p>`;}
function resultHTML(){const means=M.means(type),r=M.records(type),mx=Math.max(...means.map(x=>x.dryG));return '<div class="c-data-label">教学模拟 · 每处理 n=4 · 无显著性标注</div>'+means.map((m,t)=>`<div class="c-bar"><span>${M.treatments[t]}</span><i style="width:${m.dryG/mx*60}%;background:${M.colors[t]}"></i><b>${m.dryG.toFixed(2)} g</b></div>`).join('')+'<table><tr><th>处理</th><th>平均干重 g</th><th>平均吸磷 mg</th></tr>'+means.map((m,t)=>`<tr><td>${M.treatments[t]}</td><td>${m.dryG.toFixed(2)}</td><td>${m.uptakeMg.toFixed(2)}</td></tr>`).join('')+'</table><details><summary>展开 12 个独立单位的模拟记录</summary><table><tr><th>处理 / 重复</th><th>干重 g</th><th>P g/kg</th><th>吸磷 mg</th></tr>'+r.map(x=>`<tr><td>${M.treatments[x.treatment]} / ${x.rep}</td><td>${x.dryG.toFixed(1)}</td><td>${x.pGkg.toFixed(2)}</td><td>${x.uptakeMg.toFixed(2)}</td></tr>`).join('')+'</table></details>';}
function refreshPanel(){const a=steps[state.step];const ops=CulturePractical.get(type,state.step);$('c-operations').replaceChildren(...(ops||[]).map((text,i)=>{const b=document.createElement('button');b.textContent=text;b.dataset.operation=i;b.setAttribute('aria-pressed',String(i===state.operation));b.onclick=()=>{stop();state.operation=i;refreshPanel()};return b}));$('c-operations').hidden=!ops;$('c-eyebrow').textContent=`${String(state.step+1).padStart(2,'0')} / ${a[0]}`;$('c-heading').textContent=a[1];$('c-chain').textContent=a[2];$('c-points').replaceChildren(...a[3].map(t=>{const li=document.createElement('li');li.textContent=t;return li}));const d=M.dose(type,state.treatment,5);$('c-live').textContent=state.step===layoutStep?'每个区组 3 个处理，各 1 个独立单位':state.step===observeStep?`观察处理后第 ${state.day} 天 · 形态仅为示意`:type==='sand'&&[3,4,5].includes(state.step)?`${M.phaseNames[state.phase]} · ${M.irrigation(state.phase,state.fraction).pressure?'瓶内加压，止回阀关':'卸压，止回阀开'}`:`当前 ${M.treatments[state.treatment]} · ${type==='soil'?d.pMg+' mg P/盆':d.pMgL.toFixed(2)+' mg P/L'}`;$('c-recipe-body').innerHTML=recipe();$('c-results').innerHTML=state.step===resultStep?resultHTML():'';document.querySelector('#c-recipe').hidden=state.step===resultStep;$('readout').textContent=state.step===layoutStep?'12 个独立单位':state.step===resultStep?'干物质 × 磷浓度 → 吸磷量':'3 个磷水平 · N、K 等背景配平';$('description').textContent=a[1]+'。'+a[3].join('。');$('scene').setAttribute('aria-label',course.title+'。'+a[1]+'。拖动旋转，滚轮缩放。');}
function update(){document.querySelectorAll('#steps button').forEach((b,i)=>{b.classList.toggle('active',i===state.step);b.setAttribute('aria-current',i===state.step?'step':'false')});$('progress').textContent=`${state.step+1} / ${steps.length}`;$('prev').disabled=state.step===0;$('next').disabled=state.step===resultStep;controls();refreshPanel();$('scene').dataset.step=state.step;$('scene').dataset.treatment=state.treatment;}
function motion(){$('motion').textContent=w.paused?'▶ 动画':'Ⅱ 动画';$('motion').setAttribute('aria-pressed',String(!w.paused));}
let lastPhase=0;w.update=dt=>{if(state.cycle&&!w.paused){state.cycleClock+=dt;state.phase=Math.floor(state.cycleClock/4)%4;state.fraction=state.cycleClock%4/4;if(state.phase!==lastPhase){lastPhase=state.phase;refreshPanel()}}$('scene').dataset.phase=state.phase;};
function download(){const rows=[['culture','treatment','block_rep','dry_matter_g','P_concentration_g_per_kg','P_uptake_mg','data_type'],...M.records(type).map(x=>[type,'P'+x.treatment,x.rep,x.dryG,x.pGkg,x.uptakeMg.toFixed(3),'synthetic_teaching_example'])],url=URL.createObjectURL(new Blob(['\uFEFF'+rows.map(r=>r.join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=type+'-phosphorus-synthetic.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
$('prev').onclick=()=>{stop();setStep(state.step-1)};$('next').onclick=()=>{stop();setStep(state.step+1)};$('play').onclick=()=>{if(auto){stop();return}if(state.step===resultStep)setStep(0);auto=true;w.paused=false;motion();$('play').textContent='Ⅱ';$('play').setAttribute('aria-pressed','true');autoTimer=setInterval(()=>{const ops=CulturePractical.get(type,state.step);if(ops&&state.operation<ops.length-1){state.operation++;refreshPanel();return}if(state.step===resultStep){stop();return}setStep(state.step+1)},11000)};$('motion').onclick=()=>{w.paused=!w.paused;motion();if(w.paused)stop()};$('rotate').onclick=()=>{w.autoRotate=!w.autoRotate;$('rotate').setAttribute('aria-pressed',String(w.autoRotate))};w.onInteract=()=>$('rotate').setAttribute('aria-pressed','false');$('front').onclick=()=>{w.autoRotate=false;w.camera.yaw=0;w.camera.pitch=.1;w.camera.zoom=1;$('rotate').setAttribute('aria-pressed','false')};$('tilt').onclick=()=>{w.autoRotate=false;w.camera.pitch=w.camera.pitch>.8?.24:1.1;$('rotate').setAttribute('aria-pressed','false')};$('reset').onclick=()=>{stop();Object.assign(state,{treatment:1,day:28,aeration:true,seed:73,layout:M.layout(73)});w.resetView();w.paused=false;setStep(0);motion()};$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{$('fullscreen').textContent='F11 全屏'}};document.addEventListener('visibilitychange',()=>{if(document.hidden)stop()});document.addEventListener('keydown',e=>{if(['INPUT','BUTTON','A','CANVAS','SUMMARY'].includes(document.activeElement.tagName))return;if(e.key==='ArrowRight'){stop();setStep(state.step+1);e.preventDefault()}else if(e.key==='ArrowLeft'){stop();setStep(state.step-1);e.preventDefault()}else if(e.code==='Space'){$('play').click();e.preventDefault()}});
window.cultureDiagnostics={get state(){return JSON.parse(JSON.stringify(state))},get camera(){return {...w.camera}},get time(){return w.time},get paused(){return w.paused},get primitives(){return w.items.length},get water(){return M.irrigation(state.phase,state.fraction)}};setStep(0);motion();
})();




